"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2189],{22189:n=>{n.exports=JSON.parse('{"id":"base-01","slug":"base-01","trackId":"base","order":2,"title":"Блокчейн и криптовалюта","subtitle":"Понятные правила защиты капитала","estimatedMinutes":5,"access":"free","quizCount":3,"blueprintCount":0,"trainerIds":["HUB-CALC-06"],"markdown":"Урок 1 \xb7 4 мин \\n\\n## Блокчейн \\n\\nЧто такое блокчейн и криптовалюта \\n\\nЕсли совсем просто, криптовалюта — это цифровой актив, который можно хранить и передавать через специальную сеть — блокчейн. Чтобы понять, зачем вообще понадобилась такая система, проще всего сравнить её с обычными деньгами. \\n\\n### Крипта vs обычные деньги \\n\\nКогда ты пользуешься обычными деньгами, почти всегда между тобой и другим человеком есть посредник. Если ты переводишь деньги другу — перевод проходит через банк. Если платишь картой в магазине — участвуют банк и платёжная система. Если получаешь зарплату — деньги снова проходят через банковскую инфраструктуру. \\n\\nИменно банки ведут учёт того, сколько денег находится на твоём счёте и какие операции с ними происходили. Они же могут устанавливать лимиты, отклонять операции или блокировать доступ к счёту в определённых ситуациях. Криптовалюты предложили другой подход. \\n\\nВместо одного банка, который хранит всю историю операций у себя, существует сеть участников, которая совместно поддерживает эту историю и работает по заранее установленным правилам. Поэтому перевод криптовалюты может происходить напрямую между двумя участниками сети без обязательного банка-посредника. Это одна из ключевых идей криптовалют: \\n\\nдать людям возможность передавать ценность друг другу через открытую сеть, а не только через централизованные финансовые организации. \\n\\n### Блокчейн как общая тетрадь \\n\\nТеперь представь большую общую тетрадь. В ней записано, что один человек отправил другому определённое количество криптовалюты. Появляется новый перевод — в тетради появляется новая запись. Главное отличие в том, что эта тетрадь не лежит в сейфе одного банка. \\n\\nКопии истории операций хранят и проверяют множество участников сети. Если появляется новая операция, сеть должна согласиться с тем, что она соответствует правилам. После этого запись добавляется в общую историю. Именно эта общая история операций и называется блокчейном . \\n\\nПо сути, блокчейн позволяет множеству незнакомых людей пользоваться одной системой и соглашаться с тем, какие операции в ней действительно произошли. При этом им не обязательно доверять одному конкретному банку или компании. \\n\\nНажми, чтобы приблизить \\n\\n### Почему он называется blockchain \\n\\nСлово blockchain буквально переводится как \xabцепочка блоков\xbb . Операции в такой системе объединяются в группы — блоки. Когда один блок заполнен и подтверждён, за ним появляется следующий. Получается последовательность: \\n\\nБлок 1 → Блок 2 → Блок 3 → Блок 4 \\n\\nКаждый новый блок связан с предыдущим. Благодаря этому вся история операций выстраивается в одну последовательную цепочку. Старые записи нельзя просто незаметно переписать задним числом. Если попытаться изменить информацию в одном из предыдущих блоков, это нарушит связи с последующими блоками, и другие участники сети увидят несоответствие. \\n\\nПоэтому информация в блокчейне считается очень устойчивой к изменению. \\n\\nПопробуй тихо переписать старую запись \\n- \\n- \\n- \\n- Блоки сцеплены друг с другом. Нажми на любой, кроме последнего, — допиши себе лишний ноль. \\n\\n### Кто ведёт эту тетрадь \\n\\nЛогичный вопрос: \\n\\nесли нет одного банка, кто решает, какие операции правильные? Это делает сама сеть. Участники сети проверяют новые операции по установленным правилам и приходят к согласию о том, какие из них можно добавить в блокчейн. В разных блокчейнах этот процесс устроен по-разному. \\n\\nСейчас нам не обязательно разбираться в технических деталях. Важно понять общий принцип: \\n\\nне один человек или организация решает, какая версия истории правильная — это определяется правилами сети и её участниками. \\n\\n### Как выглядит обычный перевод \\n\\nПредставим простой пример. Маша хочет отправить Саше криптовалюту. Она создаёт перевод. Информация об этой операции поступает в сеть. \\n\\nСеть проверяет, соответствует ли перевод установленным правилам. Если всё в порядке, операция подтверждается и добавляется в блокчейн. После этого у сети появляется обновлённая история: \\n\\nМаша отправила Саше определённое количество криптовалюты. Ты можешь представить это как новую строку в той самой общей тетради. Только вместо одного банка эту историю одновременно поддерживает распределённая сеть. \\n\\n### Зачем всё это вообще нужно \\n\\nВ обычной финансовой системе мы постоянно доверяем посредникам. Мы доверяем банку, что он правильно считает деньги на нашем счёте. Доверяем платёжной системе, что она проведёт перевод. Доверяем инфраструктуре, через которую проходят наши операции. \\n\\nБлокчейн предложил другой подход. Вместо необходимости доверять одному посреднику можно создать систему, где правила заранее известны, а история операций подтверждается сетью. Это не значит, что блокчейн автоматически лучше банковской системы во всём. У каждой модели есть свои плюсы, минусы и риски. \\n\\nНо именно блокчейн впервые позволил создать цифровые активы, которые можно передавать между людьми через интернет без обязательного участия банка. Так появились криптовалюты. Самый известный пример — Bitcoin. Позже появились тысячи других криптовалют и блокчейнов, каждый со своими задачами и правилами. \\n\\nНо базовая идея остаётся той же: \\n\\nблокчейн — это способ вести общую историю операций без единого центрального владельца, а криптовалюта — один из видов цифровых активов, которые могут существовать и передаваться внутри такой системы. \\n\\nВ следующей статье мы поговорим о безопасности. Безопасность в крипте - это самая важная задача. \\n\\n### Проверь себя 1 / 2 \\n\\nВ чём главное отличие блокчейна от обычной банковской базы данных? \\n\\n\\n### Встроенные термины урока:\\n- **Блокчейн** — таблица всех транзакций, которую видят все: добавить запись можно, изменить старую нельзя. Хранится одновременно на миллионах компьютеров, поэтому подделать историю физически невозможно\\n\\n### Проверочный тест после урока (\xabПроверь себя\xbb):\\n**Вопрос 1: В чём главное отличие блокчейна от обычной банковской базы данных?**\\n- ⚪ Вариант 1: Блокчейн хранится только на компьютере владельца криптовалюты\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 2: Историю операций поддерживает сеть участников, а не один центральный банк\\n- ⚪ Вариант 3: В блокчейне можно удалить любую старую операцию\\n\\n**Вопрос 2: Что происходит после того, как операция попадает в блокчейн?**\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 1: Она становится частью общей истории операций сети\\n- ⚪ Вариант 2: Она автоматически удаляется через несколько дней\\n- ⚪ Вариант 3: Её можно отменить через поддержку блокчейна\\n\\n\\n---","blueprints":[],"quiz":[{"id":"q-base-01-1","prompt":"В чём главное отличие блокчейна от обычной банковской базы данных?","options":[{"id":"base-01-1-1","label":"Блокчейн хранится только на компьютере владельца криптовалюты","isCorrect":false,"feedback":"Неверно. Историю операций поддерживает сеть участников, а не один центральный банк"},{"id":"base-01-1-2","label":"Историю операций поддерживает сеть участников, а не один центральный банк","isCorrect":true,"feedback":"Верно. Историю операций поддерживает сеть участников, а не один центральный банк"},{"id":"base-01-1-3","label":"В блокчейне можно удалить любую старую операцию","isCorrect":false,"feedback":"Неверно. Историю операций поддерживает сеть участников, а не один центральный банк"}],"explanation":"Историю операций поддерживает сеть участников, а не один центральный банк","sourceRef":"CAPITAL_BASE:312–315 (Verbatim)"},{"id":"q-base-01-2","prompt":"Что происходит после того, как операция попадает в блокчейн?","options":[{"id":"base-01-2-1","label":"Она становится частью общей истории операций сети","isCorrect":true,"feedback":"Верно. Она становится частью общей истории операций сети"},{"id":"base-01-2-2","label":"Она автоматически удаляется через несколько дней","isCorrect":false,"feedback":"Неверно. Она становится частью общей истории операций сети"},{"id":"base-01-2-3","label":"Её можно отменить через поддержку блокчейна","isCorrect":false,"feedback":"Неверно. Она становится частью общей истории операций сети"}],"explanation":"Она становится частью общей истории операций сети","sourceRef":"CAPITAL_BASE:317–320 (Verbatim)"},{"id":"q-base-01-3","prompt":"Почему изменение одной записи нарушает проверку цепочки блоков?","options":[{"id":"base-01-3-1","label":"Хеш изменённого блока перестаёт совпадать со ссылкой в следующем блоке","isCorrect":true,"feedback":"Верно. Следующий блок хранит хеш предыдущего; подмена нарушает проверяемую связь."},{"id":"base-01-3-2","label":"Кошелёк автоматически возвращает все переводы отправителям","isCorrect":false,"feedback":"Нет. Обратного перевода не возникает; узлы обнаруживают несовпадение хешей."},{"id":"base-01-3-3","label":"Старые записи свободно меняются без следа","isCorrect":false,"feedback":"Нет. Изменение данных меняет хеш и нарушает связь со следующим блоком."}],"explanation":"Каждый блок связан с предыдущим его хешем. Проверка выявляет подмену данных; устойчивость реальной сети также зависит от правил консенсуса.","sourceRef":"00_FREE_GIFT_MakeCash_Crypto_And_Capital_Base_15_Lessons.md:254–299; source-grounded addition to the 86-question specification table"}],"source":{"file":"00_FREE_GIFT_MakeCash_Crypto_And_Capital_Base_15_Lessons.md","sha256":"88a3efb162434bb8a9b3b000caee579d9c27005a8ea46ddf4ef9cafb50dc45cc","lineStart":221,"lineEnd":325}}')}}]);